-- =============================================
-- CURSO: SEO y Posicionamiento Web (MKT-0002)
-- =============================================
SELECT c.id, 'Fundamentos del SEO', 'Conceptos básicos de posicionamiento web', 1
FROM cursos c WHERE c.codigo = 'MKT-0002'
AND NOT EXISTS (SELECT 1 FROM modulos m WHERE m.curso_id = c.id AND m.orden = 1);

SELECT c.id, 'Investigación de Palabras Clave', 'Herramientas y estrategias de keyword research', 2
FROM cursos c WHERE c.codigo = 'MKT-0002'
AND NOT EXISTS (SELECT 1 FROM modulos m WHERE m.curso_id = c.id AND m.orden = 2);

SELECT c.id, 'SEO On-Page', 'Optimización dentro de tu sitio web', 3
FROM cursos c WHERE c.codigo = 'MKT-0002'
AND NOT EXISTS (SELECT 1 FROM modulos m WHERE m.curso_id = c.id AND m.orden = 3);

SELECT c.id, 'SEO Off-Page y Link Building', 'Estrategias de autoridad externa', 4
FROM cursos c WHERE c.codigo = 'MKT-0002'
AND NOT EXISTS (SELECT 1 FROM modulos m WHERE m.curso_id = c.id AND m.orden = 4);

SELECT c.id, 'Google Search Console y Analítica', 'Medición y seguimiento de resultados', 5
FROM cursos c WHERE c.codigo = 'MKT-0002'
AND NOT EXISTS (SELECT 1 FROM modulos m WHERE m.curso_id = c.id AND m.orden = 5);

